use tonic::{transport::Server, Request, Response, Status}; use std::collections::HashMap; use std::sync::{Arc, Mutex}; use tracing::{info, warn}; use tracing_subscriber; pub mod invalidator { tonic::include_proto!("invalidator"); } use invalidator::cache_manager_server::{CacheManager, CacheManagerServer}; use invalidator::{InvalidateRequest, InvalidateResponse, BatchInvalidateRequest}; struct MyCacheManager { storage: Arc<Mutex<HashMap<String, String>>>, } #[tonic::async_trait] impl CacheManager for MyCacheManager { async fn invalidate_key(&self, request: Request<InvalidateRequest>) -> Result<Response<InvalidateResponse>, Status> { let sku = request.into_inner().sku; let mut cache = self.storage.lock().unwrap(); if cache.remove(&sku).is_some() { Ok(Response::new(InvalidateResponse { success: true, message: format!("SKU {} invalidated", sku) })) } else { Ok(Response::new(InvalidateResponse { success: true, message: "Not found".to_string() })) } } async fn invalidate_batch(&self, request: Request<BatchInvalidateRequest>) -> Result<Response<InvalidateResponse>, Status> { let skus = request.into_inner().skus; let mut cache = self.storage.lock().unwrap(); let mut count = 0; for sku in skus { if cache.remove(&sku).is_some() { count += 1; } } Ok(Response::new(InvalidateResponse { success: true, message: format!("Invalidated {} keys", count) })) } } #[tokio::main] async fn main() -> Result<(), Box<dyn std::error::Error>> { tracing_subscriber::fmt::init(); let addr = "[::1]:50051".parse()?; let cache_manager = MyCacheManager { storage: Arc::new(Mutex::new(HashMap::new())) }; Server::builder().add_service(CacheManagerServer::new(cache_manager)).serve(addr).await?; Ok(()) }
